=== FILE: axi4_lite_regs.v ===
`timescale 1ns / 1ps
`default_nettype none

// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md (holding registers,
// READY from state only, one outstanding transaction per direction).
module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,

    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,

    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,

    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,

    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,

    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
    localparam [1:0]   RESP_OKAY   = 2'b00;
    localparam [1:0]   RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held;
    reg [DATA_WIDTH-1:0] w_data_q;
    reg [STRB_WIDTH-1:0] w_strb_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [DATA_WIDTH-1:0] rdata_q;
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    // ------------------------------------------------------------------
    // Handshakes: READY is a function of state only
    // ------------------------------------------------------------------
    wire awready_int = !aw_held && !bvalid_q;
    wire wready_int  = !w_held && !bvalid_q;
    wire arready_int = !rvalid_q;

    wire aw_hs = s_axil_awvalid && awready_int;
    wire w_hs  = s_axil_wvalid && wready_int;
    wire ar_hs = s_axil_arvalid && arready_int;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held ? w_data_q : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held ? w_strb_q : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode and SLVERR policy
    // ------------------------------------------------------------------
    wire wr_mapped = (wr_addr[1:0] == 2'b00) &&
                     ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire ar_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                     ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

    wire [1:0] wr_idx = wr_addr[3:2];
    wire       wr_en  = do_write && wr_mapped;

    // ------------------------------------------------------------------
    // Byte-enable merge
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_mask
            assign wr_mask[8*g +: 8] = {8{wr_strb[g]}};
        end
    endgenerate

    wire [DATA_WIDTH-1:0] reg0_d = (reg0 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] reg1_d = (reg1 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] reg2_d = (reg2 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] reg3_d = (reg3 & ~wr_mask) | (wr_data & wr_mask);

    wire we0 = wr_en && (wr_idx == 2'd0);
    wire we1 = wr_en && (wr_idx == 2'd1);
    wire we2 = wr_en && (wr_idx == 2'd2);
    wire we3 = wr_en && (wr_idx == 2'd3);

    // ------------------------------------------------------------------
    // Next state
    // ------------------------------------------------------------------
    wire aw_held_d = (aw_held || aw_hs) && !do_write;
    wire w_held_d  = (w_held || w_hs) && !do_write;
    wire bvalid_d  = do_write || (bvalid_q && !s_axil_bready);
    wire rvalid_d  = ar_hs || (rvalid_q && !s_axil_rready);

    reg [DATA_WIDTH-1:0] rd_sel;
    always @* begin
        case (s_axil_araddr[3:2])
            2'd0:    rd_sel = reg0;
            2'd1:    rd_sel = reg1;
            2'd2:    rd_sel = reg2;
            2'd3:    rd_sel = reg3;
            default: rd_sel = {DATA_WIDTH{1'b0}};
        endcase
    end

    // ------------------------------------------------------------------
    // Write channel registers
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held   <= 1'b0;
            w_held    <= 1'b0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_data_q  <= {DATA_WIDTH{1'b0}};
            w_strb_q  <= {STRB_WIDTH{1'b0}};
        end else begin
            aw_held  <= aw_held_d;
            w_held   <= w_held_d;
            bvalid_q <= bvalid_d;
            if (aw_hs && !do_write) begin
                aw_addr_q <= s_axil_awaddr;
            end
            if (w_hs && !do_write) begin
                w_data_q <= s_axil_wdata;
                w_strb_q <= s_axil_wstrb;
            end
            if (do_write) begin
                bresp_q <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channel registers
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            rvalid_q <= 1'b0;
            rresp_q  <= RESP_OKAY;
            rdata_q  <= {DATA_WIDTH{1'b0}};
        end else begin
            rvalid_q <= rvalid_d;
            if (ar_hs) begin
                rresp_q <= ar_mapped ? RESP_OKAY : RESP_SLVERR;
                rdata_q <= ar_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
            end
        end
    end

    // ------------------------------------------------------------------
    // Register file
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            if (we0) reg0 <= reg0_d;
            if (we1) reg1 <= reg1_d;
            if (we2) reg2 <= reg2_d;
            if (we3) reg3 <= reg3_d;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = awready_int;
    assign s_axil_wready  = wready_int;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = arready_int;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;

    // ------------------------------------------------------------------
    // Design-intent properties
    // ------------------------------------------------------------------
`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!aresetn);
        if (!aresetn) assume (!s_axil_awvalid && !s_axil_wvalid && !s_axil_arvalid);
    end

    // Manager rules: VALID and payload hold until READY.
    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready))
                assume (s_axil_awvalid && (s_axil_awaddr == $past(s_axil_awaddr)));
            if ($past(s_axil_wvalid && !s_axil_wready))
                assume (s_axil_wvalid && (s_axil_wdata == $past(s_axil_wdata))
                        && (s_axil_wstrb == $past(s_axil_wstrb)));
            if ($past(s_axil_arvalid && !s_axil_arready))
                assume (s_axil_arvalid && (s_axil_araddr == $past(s_axil_araddr)));
        end
    end

    // Subordinate rules on B and R.
    always @(posedge aclk) begin
        if (f_past_valid && !$past(aresetn)) begin
            assert (!s_axil_bvalid && !s_axil_rvalid && !aw_held && !w_held);
        end
        if (f_past_valid && $past(aresetn)) begin
            if ($past(s_axil_bvalid && !s_axil_bready))
                assert (s_axil_bvalid && (s_axil_bresp == $past(s_axil_bresp)));
            if ($past(s_axil_rvalid && !s_axil_rready))
                assert (s_axil_rvalid && (s_axil_rresp == $past(s_axil_rresp))
                        && (s_axil_rdata == $past(s_axil_rdata)));
            if (!$past(s_axil_bvalid))
                assert (s_axil_bvalid == $past(do_write));
            if (!$past(s_axil_rvalid))
                assert (s_axil_rvalid == $past(ar_hs));
        end
    end

    always @(*) begin
        if (f_past_valid) begin
            assert (!(aw_held && w_held));
            if (bvalid_q) assert (!aw_held && !w_held);
            assert ((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
            assert ((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
            if (rresp_q == RESP_SLVERR) assert (rdata_q == {DATA_WIDTH{1'b0}});
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover (s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_OKAY));
            cover (s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_SLVERR));
            cover (s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_OKAY));
            cover (s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_SLVERR));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axi4_lite_regs_tb.v ===
`timescale 1ns / 1ps
`default_nettype none

`define TB_CHECK(cond, msg) \
    begin \
        if (cond) passed = passed + 1; \
        else begin \
            failed = failed + 1; \
            $error("%0t: %s", $time, msg); \
        end \
    end

`define TB_CHECK_EQ(got, exp, msg) \
    begin \
        if ((got) === (exp)) passed = passed + 1; \
        else begin \
            failed = failed + 1; \
            $error("%0t: %s: got 0x%0h expected 0x%0h", $time, msg, got, exp); \
        end \
    end

module axi4_lite_regs_tb;

    localparam [1:0]   RESP_OKAY   = 2'b00;
    localparam [1:0]   RESP_SLVERR = 2'b10;
    localparam integer TIMEOUT     = 40;

    reg         aclk = 1'b0;
    reg         aresetn;
    reg  [3:0]  s_axil_awaddr;
    reg         s_axil_awvalid;
    wire        s_axil_awready;
    reg  [31:0] s_axil_wdata;
    reg  [3:0]  s_axil_wstrb;
    reg         s_axil_wvalid;
    wire        s_axil_wready;
    wire [1:0]  s_axil_bresp;
    wire        s_axil_bvalid;
    reg         s_axil_bready;
    reg  [3:0]  s_axil_araddr;
    reg         s_axil_arvalid;
    wire        s_axil_arready;
    wire [31:0] s_axil_rdata;
    wire [1:0]  s_axil_rresp;
    wire        s_axil_rvalid;
    reg         s_axil_rready;

    integer        passed;
    integer        failed;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];

    always #5 aclk = ~aclk;

    axi4_lite_regs #(
        .ADDR_WIDTH(4),
        .DATA_WIDTH(32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    // Byte merge model: byte k of new_v replaces byte k of old_v when strb[k].
    function [31:0] merge;
        input [31:0] old_v;
        input [31:0] new_v;
        input [3:0]  strb;
        begin
            merge = { (strb[3] ? new_v[31:24] : old_v[31:24]),
                      (strb[2] ? new_v[23:16] : old_v[23:16]),
                      (strb[1] ? new_v[15:8]  : old_v[15:8]),
                      (strb[0] ? new_v[7:0]   : old_v[7:0]) };
        end
    endfunction

    // Synchronous reset for `cycles` rising edges, then check the idle state.
    task automatic do_reset(input integer cycles);
        integer k;
        begin
            @(negedge aclk);
            aresetn        = 1'b0;
            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;
            s_axil_arvalid = 1'b0;
            s_axil_bready  = 1'b0;
            s_axil_rready  = 1'b0;
            for (k = 0; k < cycles; k = k + 1) @(negedge aclk);
            aresetn  = 1'b1;
            model[0] = 32'd0;
            model[1] = 32'd0;
            model[2] = 32'd0;
            model[3] = 32'd0;
            #1;
            `TB_CHECK(s_axil_bvalid === 1'b0, "reset: BVALID low")
            `TB_CHECK(s_axil_rvalid === 1'b0, "reset: RVALID low")
            `TB_CHECK(s_axil_awready === 1'b1, "reset: AWREADY high")
            `TB_CHECK(s_axil_wready === 1'b1, "reset: WREADY high")
            `TB_CHECK(s_axil_arready === 1'b1, "reset: ARREADY high")
            `TB_CHECK_EQ(s_axil_bresp, RESP_OKAY, "reset: BRESP")
            `TB_CHECK_EQ(s_axil_rresp, RESP_OKAY, "reset: RRESP")
            `TB_CHECK_EQ(s_axil_rdata, 32'd0, "reset: RDATA")
        end
    endtask

    // One write. AW and W are raised aw_dly and w_dly cycles after the start;
    // BREADY is held low for b_dly cycles of BVALID (b_dly == 0: high throughout).
    task automatic axi_write(
        input [3:0]   addr,
        input [31:0]  data,
        input [3:0]   strb,
        input integer aw_dly,
        input integer w_dly,
        input integer b_dly
    );
        integer   cyc;
        integer   cmpl_cyc;
        integer   b_wait;
        reg       aw_done;
        reg       w_done;
        reg       b_done;
        reg       b_seen;
        reg       aw_hs_n;
        reg       w_hs_n;
        reg       b_hs_n;
        reg       mapped;
        reg [1:0] exp_resp;
        reg [1:0] first_resp;
        begin
            mapped     = (addr[1:0] == 2'b00);
            exp_resp   = mapped ? RESP_OKAY : RESP_SLVERR;
            cyc        = 0;
            cmpl_cyc   = -1;
            b_wait     = 0;
            aw_done    = 1'b0;
            w_done     = 1'b0;
            b_done     = 1'b0;
            b_seen     = 1'b0;
            first_resp = 2'b00;
            while (!b_done && (cyc < TIMEOUT)) begin
                @(negedge aclk);
                if (s_axil_bvalid === 1'b1) begin
                    `TB_CHECK(cmpl_cyc >= 0, "write: BVALID before both AW and W were accepted")
                    if (!b_seen) begin
                        b_seen     = 1'b1;
                        first_resp = s_axil_bresp;
                        `TB_CHECK((cyc - cmpl_cyc) <= 2, "write: latency above the 2-cycle bound")
                        `TB_CHECK_EQ(s_axil_bresp, exp_resp, "write: BRESP")
                    end else begin
                        `TB_CHECK_EQ(s_axil_bresp, first_resp, "write: BRESP changed while BREADY low")
                    end
                    s_axil_bready = (b_wait >= b_dly);
                    b_wait = b_wait + 1;
                end else begin
                    `TB_CHECK(!b_seen, "write: BVALID dropped before BREADY")
                    if (cmpl_cyc >= 0) begin
                        `TB_CHECK((cyc - cmpl_cyc) <= 2, "write: no BVALID within 2 cycles of the request")
                    end
                    s_axil_bready = (b_dly == 0);
                end

                if (!aw_done && (cyc >= aw_dly)) begin
                    s_axil_awvalid = 1'b1;
                    s_axil_awaddr  = addr;
                end else begin
                    s_axil_awvalid = 1'b0;
                    s_axil_awaddr  = ~addr;
                end
                if (!w_done && (cyc >= w_dly)) begin
                    s_axil_wvalid = 1'b1;
                    s_axil_wdata  = data;
                    s_axil_wstrb  = strb;
                end else begin
                    s_axil_wvalid = 1'b0;
                    s_axil_wdata  = ~data;
                    s_axil_wstrb  = ~strb;
                end

                #1;
                `TB_CHECK(s_axil_awready === !aw_done, "write: AWREADY")
                `TB_CHECK(s_axil_wready === !w_done, "write: WREADY")

                aw_hs_n = s_axil_awvalid && s_axil_awready;
                w_hs_n  = s_axil_wvalid && s_axil_wready;
                b_hs_n  = s_axil_bvalid && s_axil_bready;
                if (aw_hs_n) aw_done = 1'b1;
                if (w_hs_n) w_done = 1'b1;
                if ((aw_hs_n || w_hs_n) && aw_done && w_done) cmpl_cyc = cyc;
                if (b_hs_n) b_done = 1'b1;
                cyc = cyc + 1;
            end
            `TB_CHECK(b_done, "write: no write response before the timeout")
            if (mapped) model[addr[3:2]] = merge(model[addr[3:2]], data, strb);
        end
    endtask

    // One read. AR is raised ar_dly cycles after the start; RREADY is held low
    // for r_dly cycles of RVALID (r_dly == 0: high throughout).
    task automatic axi_read(
        input [3:0]   addr,
        input integer ar_dly,
        input integer r_dly
    );
        integer    cyc;
        integer    ar_cyc;
        integer    r_wait;
        reg        ar_done;
        reg        r_done;
        reg        r_seen;
        reg        ar_hs_n;
        reg        r_hs_n;
        reg        mapped;
        reg [1:0]  exp_resp;
        reg [1:0]  first_resp;
        reg [31:0] exp_data;
        reg [31:0] first_data;
        begin
            mapped     = (addr[1:0] == 2'b00);
            exp_resp   = mapped ? RESP_OKAY : RESP_SLVERR;
            exp_data   = mapped ? model[addr[3:2]] : 32'd0;
            cyc        = 0;
            ar_cyc     = -1;
            r_wait     = 0;
            ar_done    = 1'b0;
            r_done     = 1'b0;
            r_seen     = 1'b0;
            first_resp = 2'b00;
            first_data = 32'd0;
            while (!r_done && (cyc < TIMEOUT)) begin
                @(negedge aclk);
                if (s_axil_rvalid === 1'b1) begin
                    `TB_CHECK(ar_cyc >= 0, "read: RVALID before AR was accepted")
                    if (!r_seen) begin
                        r_seen     = 1'b1;
                        first_resp = s_axil_rresp;
                        first_data = s_axil_rdata;
                        `TB_CHECK((cyc - ar_cyc) <= 2, "read: latency above the 2-cycle bound")
                        `TB_CHECK_EQ(s_axil_rresp, exp_resp, "read: RRESP")
                        `TB_CHECK_EQ(s_axil_rdata, exp_data, "read: RDATA")
                    end else begin
                        `TB_CHECK_EQ(s_axil_rresp, first_resp, "read: RRESP changed while RREADY low")
                        `TB_CHECK_EQ(s_axil_rdata, first_data, "read: RDATA changed while RREADY low")
                    end
                    s_axil_rready = (r_wait >= r_dly);
                    r_wait = r_wait + 1;
                end else begin
                    `TB_CHECK(!r_seen, "read: RVALID dropped before RREADY")
                    if (ar_cyc >= 0) begin
                        `TB_CHECK((cyc - ar_cyc) <= 2, "read: no RVALID within 2 cycles of the request")
                    end
                    s_axil_rready = (r_dly == 0);
                end

                if (!ar_done && (cyc >= ar_dly)) begin
                    s_axil_arvalid = 1'b1;
                    s_axil_araddr  = addr;
                end else begin
                    s_axil_arvalid = 1'b0;
                    s_axil_araddr  = ~addr;
                end

                #1;
                `TB_CHECK(s_axil_arready === !ar_done, "read: ARREADY")

                ar_hs_n = s_axil_arvalid && s_axil_arready;
                r_hs_n  = s_axil_rvalid && s_axil_rready;
                if (ar_hs_n) begin
                    ar_done = 1'b1;
                    ar_cyc  = cyc;
                end
                if (r_hs_n) r_done = 1'b1;
                cyc = cyc + 1;
            end
            `TB_CHECK(r_done, "read: no read response before the timeout")
        end
    endtask

    task automatic read_all;
        begin
            axi_read(4'h0, 0, 0);
            axi_read(4'h4, 0, 0);
            axi_read(4'h8, 0, 0);
            axi_read(4'hC, 0, 0);
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        nonce  = {64{8'h00}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {64{8'h00}};

        aresetn        = 1'b0;
        s_axil_awaddr  = 4'h0;
        s_axil_awvalid = 1'b0;
        s_axil_wdata   = 32'h0;
        s_axil_wstrb   = 4'h0;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_araddr  = 4'h0;
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b0;
        model[0] = 32'd0;
        model[1] = 32'd0;
        model[2] = 32'd0;
        model[3] = 32'd0;

        // 1. Reset values
        do_reset(3);
        read_all;

        // 2. Write then read every register
        axi_write(4'h0, 32'h1111_1111, 4'hF, 0, 0, 0);
        axi_read(4'h0, 0, 0);
        axi_write(4'h4, 32'h2222_2222, 4'hF, 0, 0, 0);
        axi_read(4'h4, 0, 0);
        axi_write(4'h8, 32'h3333_3333, 4'hF, 0, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_write(4'hC, 32'h4444_4444, 4'hF, 0, 0, 0);
        axi_read(4'hC, 0, 0);
        read_all;

        // 3. AW/W ordering: AW first, W first, together after a gap, long gap
        axi_write(4'h0, 32'hDEAD_BEEF, 4'hF, 0, 3, 0);
        axi_write(4'h4, 32'hCAFE_F00D, 4'hF, 3, 0, 0);
        axi_write(4'h8, 32'h0123_4567, 4'hF, 2, 2, 0);
        axi_write(4'hC, 32'h89AB_CDEF, 4'hF, 1, 5, 0);
        axi_write(4'h0, 32'h0BAD_F00D, 4'hF, 6, 1, 0);
        read_all;

        // 4. Byte strobes: partial and empty
        axi_write(4'h0, 32'hAABB_CCDD, 4'b0001, 0, 0, 0);
        axi_write(4'h4, 32'hAABB_CCDD, 4'b0110, 0, 0, 0);
        axi_write(4'h8, 32'hAABB_CCDD, 4'b1000, 0, 0, 0);
        axi_write(4'hC, 32'hAABB_CCDD, 4'b1010, 2, 0, 0);
        axi_write(4'h0, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);
        axi_write(4'h4, 32'h1234_5678, 4'b0000, 0, 2, 0);
        read_all;

        // 5. Back-pressure on B and R
        axi_write(4'h4, 32'h5555_AAAA, 4'hF, 0, 0, 4);
        axi_write(4'h8, 32'h6666_9999, 4'hF, 1, 0, 2);
        axi_write(4'h9, 32'h7777_8888, 4'hF, 0, 1, 3);
        axi_read(4'h4, 0, 5);
        axi_read(4'h8, 2, 3);
        axi_read(4'h5, 0, 4);

        // 6. Back-to-back transactions with no idle cycles
        axi_write(4'h0, 32'hA000_0001, 4'hF, 0, 0, 0);
        axi_write(4'h4, 32'hA000_0002, 4'hF, 0, 0, 0);
        axi_write(4'h8, 32'hA000_0003, 4'hF, 0, 0, 0);
        axi_write(4'hC, 32'hA000_0004, 4'hF, 0, 0, 0);
        axi_read(4'h0, 0, 0);
        axi_read(4'h4, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_read(4'hC, 0, 0);

        // 7. SLVERR policy: misaligned writes change nothing, reads return zero
        axi_write(4'h5, 32'hBAD0_0005, 4'hF, 0, 0, 0);
        axi_write(4'h2, 32'hBAD0_0002, 4'hF, 0, 0, 0);
        axi_write(4'hE, 32'hBAD0_000E, 4'hF, 0, 0, 0);
        axi_write(4'h1, 32'hBAD0_0001, 4'hF, 1, 0, 0);
        axi_write(4'hB, 32'hBAD0_000B, 4'hF, 0, 2, 1);
        axi_write(4'h7, 32'hBAD0_0007, 4'h0, 0, 0, 0);
        axi_read(4'h1, 0, 0);
        axi_read(4'h3, 0, 0);
        axi_read(4'h6, 0, 0);
        axi_read(4'hE, 0, 0);
        axi_read(4'hF, 1, 2);
        read_all;

        // 8. Read and write in flight together
        fork
            axi_write(4'h0, 32'h0F0F_0F0F, 4'hF, 0, 0, 0);
            axi_read(4'h4, 0, 0);
        join
        fork
            axi_write(4'hC, 32'hF0F0_F0F0, 4'hF, 0, 2, 3);
            axi_read(4'h8, 0, 2);
        join
        fork
            axi_write(4'h6, 32'h1234_5678, 4'hF, 1, 1, 0);
            axi_read(4'h7, 1, 1);
        join
        fork
            axi_write(4'h4, 32'h0000_C0DE, 4'b0011, 2, 0, 1);
            axi_read(4'hC, 1, 3);
        join
        read_all;

        // 9a. Reset discards a half-accepted write
        axi_write(4'h4, 32'h7777_7777, 4'hF, 0, 0, 0);
        @(negedge aclk);
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h4;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b1;
        #1;
        `TB_CHECK(s_axil_awready === 1'b1, "half write: AWREADY high")
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        #1;
        `TB_CHECK(s_axil_awready === 1'b0, "half write: AWREADY low while AW held")
        `TB_CHECK(s_axil_wready === 1'b1, "half write: WREADY high while AW held")
        `TB_CHECK(s_axil_bvalid === 1'b0, "half write: no BVALID")
        do_reset(2);
        axi_write(4'h8, 32'hA5A5_5A5A, 4'hF, 4, 0, 0);
        axi_read(4'h4, 0, 0);
        axi_read(4'h8, 0, 0);

        // 9b. Reset drops a pending B and a pending R
        @(negedge aclk);
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h0;
        s_axil_wvalid  = 1'b1;
        s_axil_wdata   = 32'h1357_9BDF;
        s_axil_wstrb   = 4'hF;
        s_axil_bready  = 1'b0;
        s_axil_arvalid = 1'b1;
        s_axil_araddr  = 4'h8;
        s_axil_rready  = 1'b0;
        #1;
        `TB_CHECK(s_axil_awready === 1'b1, "pending: AWREADY high")
        `TB_CHECK(s_axil_wready === 1'b1, "pending: WREADY high")
        `TB_CHECK(s_axil_arready === 1'b1, "pending: ARREADY high")
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        s_axil_wvalid  = 1'b0;
        s_axil_arvalid = 1'b0;
        #1;
        `TB_CHECK(s_axil_bvalid === 1'b1, "pending: BVALID one cycle after the write")
        `TB_CHECK(s_axil_rvalid === 1'b1, "pending: RVALID one cycle after the read")
        `TB_CHECK_EQ(s_axil_bresp, RESP_OKAY, "pending: BRESP")
        `TB_CHECK_EQ(s_axil_rresp, RESP_OKAY, "pending: RRESP")
        `TB_CHECK_EQ(s_axil_rdata, model[2], "pending: RDATA")
        @(negedge aclk);
        #1;
        `TB_CHECK(s_axil_bvalid === 1'b1, "pending: BVALID held while BREADY low")
        `TB_CHECK(s_axil_rvalid === 1'b1, "pending: RVALID held while RREADY low")
        do_reset(1);
        read_all;

        // 10. Normal operation after reset
        axi_write(4'hC, 32'hFEED_FACE, 4'hF, 0, 0, 0);
        axi_read(4'hC, 0, 0);
        read_all;

        @(negedge aclk);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hung run ends with a failing verdict.
    initial begin
        #200000;
        $error("watchdog: the test did not finish");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

endmodule

`undef TB_CHECK
`undef TB_CHECK_EQ
`default_nettype wire
